public int search(int[] nums, int target) {
    int left = 0;
    int right = nums.length - 1;
    while (left <= right) {
        int mid = (left + right) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        if (nums[mid] >= nums[left]) {
            if (target >= nums[left] && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else {
            if (target > nums[mid] && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }
    return -1;
}

public double trimMean(int[] arr) {
    int n = arr.length;
    int k = (int) Math.round(n * 0.05);
    int[] sorted = Arrays.copyOf(arr, n);
    Arrays.sort(sorted);
    double sum = 0;
    for (int i = k; i < n - k; i++) {
        sum += sorted[i];
    }
    return sum / (n - 2 * k);
}

